style.css:
/* Включаем максимальный приоритет для подсветки активного элемента */
*:focus {
    outline: 5px solid #ff00ff !important; /* Яркий неоновый розовый контур */
    outline-offset: 2px !important;       /* Отступ контура, чтобы его было видно */
    background-color: #ffffcc !important;  /* Светло-желтый фон самого поля */
    color: #000000 !important;             /* Черный цвет текста для читаемости */
    box-shadow: 0 0 20px rgba(255, 0, 255, 0.8) !important; /* Свечение */
}

/* Отдельно для выпадающих списков и чекбоксов, чтобы их тоже было четко видно */
select:focus, input[type="checkbox"]:focus, input[type="radio"]:focus {
    outline: 5px solid #00ffff !important; /* Бирюзовый цвет для элементов выбора */
    box-shadow: 0 0 20px rgba(0, 255, 255, 0.8) !important;
}
